    var bm = s.match(/^Board (\d+) of (\d)$/); if (bm) return 'Tabuleiro ' + bm[1] + ' de ' + bm[2];
    var sm = s.match(/^(Matchday|Fowl Play) (\d+)$/); if (sm) return (sm[1] === 'Matchday' ? 'Dia de Jogo ' : 'Penas Eriçadas ') + sm[2];
